(()=>{'use strict';const key='buchee_aurora_intro_seen_v2';const slides=[{image:'https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1100&q=85',title:'Paylaş, Üret, Her Yerde Görün.',text:'Kısa videolar (Reels), fotoğraf gönderileri (Post) ve kısa yazılar (Twit) paylaş. Hepsi Buchee’de.',eyebrow:'01 / PAYLAŞ',features:[['▣','Reels Paylaş'],['▧','Post Paylaş'],['☰','Twit At']]},{image:'https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&w=1100&q=85',title:'İçerik Üret, Kazanç Elde Et.',text:'İçeriklerini paylaş, topluluğunu büyüt ve uygun olduğunda platformun sunduğu kazanç fırsatlarından yararlan.',eyebrow:'02 / KAZAN',features:[['◉','Etkileşim'],['☆','Ödüller'],['♧','Avantajlar']]},{image:'https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=1100&q=85',title:'Yerli ve Bağımsız Bir Platform.',text:'Buchee, Türkiye’de geliştirilen, kullanıcı odaklı bir sosyal medya platformudur.',eyebrow:'🇹🇷 TÜRKİYE’DE GELİŞTİRİLDİ',features:[['♢','Güvenli'],['ϟ','Hızlı'],['∞','Gelişen']]}];let step=0,shown=false;const root=document.createElement('section');root.id='buchee-aurora-intro';root.hidden=true;root.setAttribute('aria-label','Buchee tanıtımı');root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');function render(){const x=slides[step];const approved=['assets/buchee_onboarding_1.webp','assets/buchee_onboarding_2.webp','assets/buchee_onboarding_3.webp'];root.innerHTML='<div class="buchee-aurora-panel buchee-aurora-screen-'+step+'"><div class="buchee-aurora-photo" style="background-image:linear-gradient(180deg,rgba(0,0,0,.12) 0%,rgba(0,0,0,.08) 34%,rgba(0,0,0,.91) 82%,#08090e 100%),url(&quot;'+x.image+'&quot;)"></div><div class="buchee-aurora-top"><div class="buchee-aurora-brand">Buchee<span class="buchee-brand-dot">.</span></div><button type="button" class="buchee-aurora-skip" data-intro="skip">Atla</button></div><div class="buchee-aurora-bottom"><span class="buchee-aurora-eyebrow">'+x.eyebrow+'</span><h1>'+x.title+'</h1><p>'+x.text+'</p><div class="buchee-intro-features">'+x.features.map(f=>'<div class="buchee-intro-feature"><span aria-hidden="true">'+f[0]+'</span><small>'+f[1]+'</small></div>').join('')+'</div><div class="buchee-intro-navigation"><div class="buchee-aurora-dots">'+slides.map((_,i)=>'<i class="'+(i===step?'active':'')+'"></i>').join('')+'</div><button type="button" class="buchee-aurora-primary" data-intro="next" aria-label="'+(step===slides.length-1?'Hemen başla':'Sonraki tanıtım')+'">'+(step===slides.length-1?'Hemen Başla':'')+' <span aria-hidden="true">→</span></button></div><button type="button" class="buchee-aurora-secondary" data-intro="login">Hesabım var, giriş yap</button></div></div>'}function close(mode){root.hidden=true;document.body.style.removeProperty('overflow');try{localStorage.setItem(key,'1')}catch{}if(mode){const b=document.querySelector('#auth-root [data-auth="'+mode+'"]');if(b)b.click()}}root.addEventListener('click',e=>{const a=e.target.closest('[data-intro]');if(!a)return;const v=a.dataset.intro;if(v==='next'&&step<slides.length-1){step++;render()}else close(v==='login'?'login':v==='next'?'signup':null)});function check(){if(shown||!root.hidden)return;const auth=document.getElementById('auth-root'),app=document.getElementById('app-root');if(!auth||!app||auth.classList.contains('hidden')||!app.classList.contains('hidden')||!auth.querySelector('#auth-form'))return;let seen=false;try{seen=localStorage.getItem(key)==='1'}catch{}if(seen)return;shown=true;step=0;render();root.hidden=false;document.body.style.overflow='hidden'}function init(){document.body.append(root);const auth=document.getElementById('auth-root');if(auth){new MutationObserver(()=>{if(!root.hidden&&auth.classList.contains('hidden'))close();else check()}).observe(auth,{attributes:true,attributeFilter:['class'],childList:true,subtree:false})}check();setTimeout(check,600);setTimeout(check,1800)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()})();